SELECT p.organization_id AS org, m.name AS name, p.role AS role, (p.seq = t.current_seq) AS cur, count(*) AS n, count(DISTINCT p.tender_id) AS tenders FROM tender_version_parties p CROSS JOIN tenders t ON t.id = p.tender_id CROSS JOIN organization_mentions m ON m.notice_id = p.mention_notice_id AND m.section_id = p.mention_section_id WHERE p.organization_id = 30953692 AND +m.name NOT LIKE 'Northern Housing%' GROUP BY m.name, p.role, (p.seq = t.current_seq)
UNION ALL
